// Package webidl holds facts about the web platform that WebIDL states and
// TypeScript's `lib.*.d.ts` set either flattens or gets wrong. The facts are
// read from the pinned `@webref/idl` package and checked in as a Go table, so
// a conversion that consults them needs neither Node nor the network.
//
// The table is in table.go and is generated by tools/webidl_facts. See
// planning/web_api_types/design.md §5.2.
package webidl

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// Kind is the sort of WebIDL definition an entry describes.
type Kind int

const (
	// KindInterface is an `interface` definition.
	KindInterface Kind = iota
	// KindCallbackInterface is a `callback interface` definition, such as
	// `EventListener` or `NodeFilter`.
	KindCallbackInterface
	// KindNamespace is a `namespace` definition, such as `console` or `CSS`.
	KindNamespace
)

// String returns the Go identifier of the constant, which is how the
// generated table spells it.
func (k Kind) String() string {
	switch k {
	case KindInterface:
		return "KindInterface"
	case KindCallbackInterface:
		return "KindCallbackInterface"
	case KindNamespace:
		return "KindNamespace"
	}
	return fmt.Sprintf("Kind(%d)", int(k))
}

// keyword returns the WebIDL keyword that introduces a definition of kind k,
// for error messages.
func (k Kind) keyword() string {
	switch k {
	case KindCallbackInterface:
		return "callback interface"
	case KindNamespace:
		return "namespace"
	}
	return "interface"
}

// Definition is what WebIDL states about one interface, callback interface or
// namespace.
type Definition struct {
	Kind Kind

	// Exposed lists the global names from the definition's `[Exposed]`
	// attribute, as written. A name such as `Worker` stands for every global
	// scope whose `[Global]` list includes it, so `Exposed=Worker` covers
	// `DedicatedWorkerGlobalScope`, `SharedWorkerGlobalScope` and
	// `ServiceWorkerGlobalScope`. The single value `*` means every global
	// scope. Exposed is empty for a callback interface without constants,
	// which has no interface object to expose.
	Exposed []string

	// Global lists the names from the definition's `[Global]` attribute,
	// which marks it as the interface of a global scope. `Window` carries
	// `Global=Window`, and `DedicatedWorkerGlobalScope` carries
	// `Global=(Worker, DedicatedWorker)`. Global is empty for every other
	// definition.
	Global []string

	// Transferable is true when the definition carries `[Transferable]`,
	// so its instances can be moved with `postMessage` or
	// `structuredClone`.
	Transferable bool

	// Constructible is true when the interface or one of its partial
	// definitions declares a `constructor()` operation, so `new Name(...)`
	// works. A `[LegacyFactoryFunction]` such as `Image` names a separate
	// global and does not set it.
	Constructible bool
}

// Render returns the Go source of table.go for the given `@webref/idl`
// version and definitions. The output is gofmt-formatted and lists the
// definitions sorted by name, so the same input always renders the same bytes.
func Render(version string, defs map[string]Definition) ([]byte, error) {
	names := make([]string, 0, len(defs))
	for name := range defs {
		names = append(names, name)
	}
	sort.Strings(names)

	var b bytes.Buffer
	b.WriteString("// Code generated by tools/webidl_facts. DO NOT EDIT.\n\n")
	b.WriteString("package webidl\n\n")
	b.WriteString("// PinnedVersion is the `@webref/idl` version the table was read from. It\n")
	b.WriteString("// matches the version package.json pins.\n")
	fmt.Fprintf(&b, "const PinnedVersion = %s\n\n", strconv.Quote(version))
	b.WriteString("// Definitions maps the name of each interface, callback interface and\n")
	b.WriteString("// namespace in the pinned `@webref/idl` set to what WebIDL states about it.\n")
	b.WriteString("// An entry claims that the definition exists with that name and kind, is\n")
	b.WriteString("// exposed in the listed global scopes, is a global scope itself when Global\n")
	b.WriteString("// is set, and is transferable and constructible exactly when those fields\n")
	b.WriteString("// are true. Interface mixins and partial definitions have no entry of their\n")
	b.WriteString("// own.\n")
	b.WriteString("var Definitions = map[string]Definition{\n")
	for _, name := range names {
		def := defs[name]
		fmt.Fprintf(&b, "%s: {Kind: %s", strconv.Quote(name), def.Kind)
		if len(def.Exposed) > 0 {
			fmt.Fprintf(&b, ", Exposed: %s", stringSlice(def.Exposed))
		}
		if len(def.Global) > 0 {
			fmt.Fprintf(&b, ", Global: %s", stringSlice(def.Global))
		}
		if def.Transferable {
			b.WriteString(", Transferable: true")
		}
		if def.Constructible {
			b.WriteString(", Constructible: true")
		}
		b.WriteString("},\n")
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

// stringSlice returns the Go literal of values as a `[]string`.
func stringSlice(values []string) string {
	quoted := make([]string, len(values))
	for i, v := range values {
		quoted[i] = strconv.Quote(v)
	}
	return "[]string{" + strings.Join(quoted, ", ") + "}"
}

// Generate returns the Go source of table.go for the `@webref/idl` package
// installed at dir. It reads the version from the package's package.json and
// the definitions from its `.idl` files.
func Generate(dir string) ([]byte, error) {
	version, err := PackageVersion(dir)
	if err != nil {
		return nil, err
	}
	defs, err := ScanDir(dir)
	if err != nil {
		return nil, err
	}
	return Render(version, defs)
}

// PackageVersion returns the `version` field of the package.json in dir.
func PackageVersion(dir string) (string, error) {
	data, err := os.ReadFile(filepath.Join(dir, "package.json"))
	if err != nil {
		return "", err
	}
	var manifest struct {
		Version string `json:"version"`
	}
	if err := json.Unmarshal(data, &manifest); err != nil {
		return "", fmt.Errorf("%s: %w", filepath.Join(dir, "package.json"), err)
	}
	if manifest.Version == "" {
		return "", fmt.Errorf("%s has no version", filepath.Join(dir, "package.json"))
	}
	return manifest.Version, nil
}
